// src/theme.css: the theme's tokens (docs/design/look.md §3) as CSS variables the app kit's
// styles use, with the brand color's changes on top and the ux file's density and motion.
import {
  type Mode,
  type ThemeIR,
  type Tokens,
  themeNamed,
  tokensOf,
  type UxIR,
  withBackground,
} from "@smithable/core";
import { brandColors } from "./brand.js";

const HEADER =
  "/* Generated by Smithable from smithable.ux.yml. Do not edit: this file is overwritten on every change. */\n";

/** Control and row sizes per density; touch screens always get 44 px targets. */
const DENSITY = {
  comfortable: { control: "2.75rem", row: "4rem", cell: "1rem", card: "1.5rem" },
  standard: { control: "2.5rem", row: "3.5rem", cell: "0.875rem", card: "1.25rem" },
  compact: { control: "2.25rem", row: "3.25rem", cell: "0.75rem", card: "1.25rem" },
};

/**
 * Durations, easing and travel per motion setting, for the kit's dialogs, drawer, notices, rows
 * and page changes: nothing longer than a fifth of a second, since the person waits on them.
 * Lively alone adds a landing page's entrance (--landing-motion, --hero-motion), up to half a
 * second, since nobody waits on it.
 */
const MOTION = {
  none: { fast: "0ms", slow: "0ms", ease: "linear", distance: "0px" },
  subtle: { fast: "120ms", slow: "180ms", ease: "cubic-bezier(0.2, 0, 0, 1)", distance: "6px" },
  lively: {
    fast: "150ms",
    slow: "200ms",
    ease: "cubic-bezier(0.34, 1.3, 0.64, 1)",
    distance: "14px",
  },
};

/** Fonts hosted by the app itself (Fontsource, OFL); the package is added to package.json. */
export const FONT_PACKAGES: Record<string, string> = {
  Inter: "@fontsource-variable/inter",
  "Nunito Sans": "@fontsource-variable/nunito-sans",
  "Source Sans 3": "@fontsource-variable/source-sans-3",
  "Source Serif 4": "@fontsource-variable/source-serif-4",
  Fraunces: "@fontsource-variable/fraunces",
  "Archivo Narrow": "@fontsource-variable/archivo-narrow",
  "DM Sans": "@fontsource-variable/dm-sans",
  Outfit: "@fontsource-variable/outfit",
};

/** The theme the ux file names, among the built-ins and the project's own. */
export function themeOf(ux: UxIR, themes: readonly ThemeIR[] = []): ThemeIR {
  const theme = themeNamed(ux.theme.preset, themes) ?? themeNamed("modern");
  if (!theme) throw new Error("No built-in theme");
  return theme;
}

/** The font the app uses: the brand's, or the theme's. */
export function themeFont(ux: UxIR, themes: readonly ThemeIR[] = []): string {
  return ux.theme.font ?? themeOf(ux, themes).font;
}

/**
 * The theme's color tokens in one mode: the owner's background first (the colors on it derived
 * again), then a brand color on top, when there are any.
 */
/**
 * Hover and focus: an element in its own hue, a step darker in light mode and lighter in dark,
 * never another hue (Johan, 2026-10-08: the accent made editorial dark hover green). A plain
 * surface (a row, a menu item, an outline button) takes a veil of the text color.
 */
const HOVER = {
  light: `  --hover: color-mix(in oklch, var(--foreground) 7%, transparent);
  --primary-hover: color-mix(in oklch, var(--primary), black 20%);
  --destructive-hover: color-mix(in oklch, var(--destructive), black 20%);`,
  dark: `  --hover: color-mix(in oklch, var(--foreground) 10%, transparent);
  --primary-hover: color-mix(in oklch, var(--primary), white 30%);
  --destructive-hover: color-mix(in oklch, var(--destructive), white 30%);`,
};

function tokens(ux: UxIR, theme: ThemeIR, mode: Mode): Tokens {
  const base = (ux.theme.background && withBackground(theme, ux.theme.background)) || theme;
  return tokensOf(base, mode, ux.theme.primary ? brandColors(ux.theme.primary, base, mode) : {});
}

/** A landing page's ux: the app's theme with the keys the page changes (look.md §1.5). */
const pageUx = (ux: UxIR, page: string): UxIR => ({
  ...ux,
  theme: { ...ux.theme, ...ux.pages[page]?.theme },
});

/** The pages with a theme of their own. */
const themedPages = (ux: UxIR) =>
  Object.entries(ux.pages)
    .filter(([, p]) => p.theme && Object.keys(p.theme).length)
    .map(([id]) => id);

/** Every font the app shows: the app's and its landing pages' own, body and headings. */
export function themeFonts(ux: UxIR, themes: readonly ThemeIR[] = []): string[] {
  return [
    ...new Set(
      [ux, ...themedPages(ux).map((id) => pageUx(ux, id))].flatMap((u) => [
        themeFont(u, themes),
        themeOf(u, themes).style.headingFont ?? themeFont(u, themes),
      ]),
    ),
  ];
}

/**
 * A theme's style layer (docs/design/theme-lab.md §2) as CSS variables the kit reads, one field
 * at a time; no component knows a theme's name. The defaults are the modern shape, so every
 * theme renders as before, with two small differences Fable accepted (2026-10-13): corporate's
 * headings, tracked 0 before, are "normal" now (-0.01em, below what anyone sees), and minimal's
 * card edge is var(--border) where it was var(--muted).
 */
const TRACKING = { tight: "-0.02em", normal: "-0.01em", wide: "0.05em" };
/** The size of a page title and a section title against today's (regular). */
const SCALE = { small: "0.875", regular: "1", large: "1.2" };
const DIVIDER = {
  light: "var(--border)",
  strong: "color-mix(in oklch, var(--foreground) 35%, transparent)",
  none: "transparent",
};
const BUTTON_RADIUS = { rounded: "calc(var(--radius) - 2px)", pill: "9999px", square: "0" };

/** A font and what stands in for it before it loads: a serif face falls back to a serif. */
const SERIFS = ["Fraunces", "Source Serif 4"];
const fontStack = (font: string) =>
  SERIFS.includes(font)
    ? `"${font} Variable", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif`
    : `"${font} Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif`;

function styleVariables(theme: ThemeIR, bodyFont: string): Record<string, string> {
  const { style } = theme;
  const s = style.surfaces;
  return {
    "font-heading": fontStack(style.headingFont ?? bodyFont),
    "heading-weight": String(style.headings.weight),
    "heading-tracking": TRACKING[style.headings.tracking],
    "heading-scale": SCALE[style.headings.scale],
    "heading-case": style.headings.case === "upper" ? "uppercase" : "none",
    // A section's heading block: at the start, or centered with its lead under it (headings.align).
    "heading-align": style.headings.align === "center" ? "center" : "start",
    "heading-inline": style.headings.align === "center" ? "auto" : "0",
    // A card: a border (bordered), the theme's shadow alone (raised), or neither (flat).
    "card-shadow": s.cards === "flat" ? "none" : theme.shadow,
    "card-border": s.cards === "bordered" ? "1px" : "0",
    "card-border-color": s.cards === "bordered" ? "var(--border)" : "transparent",
    // A page's sections: open, or each in a box of the card's color.
    "section-background": s.sections === "boxed" ? "var(--card)" : "transparent",
    "section-border": s.sections === "boxed" ? "1px" : "0",
    "section-gap": s.sections === "boxed" ? "1.5rem" : "0",
    divider: DIVIDER[s.dividers],
    "button-radius": BUTTON_RADIUS[style.buttons.shape],
    "button-weight": style.buttons.weight === "bold" ? "700" : "600",
    // "theme" leaves each picture its own rounding (initial: the kit's fallback applies).
    "picture-radius":
      style.pictures.corners === "square"
        ? "0"
        : style.pictures.corners === "round"
          ? "9999px"
          : "initial",
    "picture-frame": style.pictures.frame === "border" ? "1px" : "0",
    "table-numbers": style.tables.numbers === "tabular" ? "tabular-nums" : "normal",
    // Rows: a line between them (lined), every other one shaded (zebra), or neither (plain).
    "row-divider": style.tables.rows === "lined" ? "var(--divider)" : "transparent",
    "row-stripe": style.tables.rows === "zebra" ? "var(--muted)" : "transparent",
  };
}

export function themeCss(ux: UxIR, themes: readonly ThemeIR[] = []): string {
  const block = (values: Record<string, string>, indent: string) =>
    Object.entries(values)
      .map(([k, v]) => `${indent}--${k}: ${v};`)
      .join("\n");
  /** One theme's variables under a selector: :root for the app, a page's own under its hook. */
  const scope = (selector: string, dark: string, from: UxIR) => {
    const theme = themeOf(from, themes);
    const font = themeFont(from, themes);
    const density = DENSITY[from.theme.density];
    const motion = MOTION[from.theme.motion];
    return {
      light: `${selector} {
${block(tokens(from, theme, "light"), "  ")}
  --radius: ${theme.radius};
  --font-body: ${fontStack(font)};
  --control-height: ${density.control};
  --row-height: ${density.row};
  --cell-padding: ${density.cell};
  --card-padding: ${density.card};
  --motion-fast: ${motion.fast};
  --motion-slow: ${motion.slow};
  --motion-ease: ${motion.ease};
  --motion-distance: ${motion.distance};
  --landing-motion: ${from.theme.motion === "lively" ? "kit-rise" : "none"};
  --hero-motion: ${from.theme.motion === "lively" ? "kit-settle" : "none"};
${block(styleVariables(theme, font), "  ")}
${HOVER.light}
}`,
      dark: `${dark} {
${block(tokens(from, theme, "dark"), "  ")}
${HOVER.dark}
}`,
      comment: `${theme.name}${from.theme.primary ? `, brand color ${from.theme.primary}` : ""}, font ${font}, ${from.theme.density}, motion ${from.theme.motion}`,
    };
  };
  // Dark as the visitor's appearance resolves on <html> (src/kit/appearance.ts): the device's
  // setting, or the one chosen.
  const app = scope(":root", ':root[data-appearance="dark"]', ux);
  // A landing page's own theme: the same variables on its body (data-page), so only it changes.
  const pages = themedPages(ux).map((id) => ({
    id,
    ...scope(`[data-page="${id}"]`, `[data-appearance="dark"] [data-page="${id}"]`, pageUx(ux, id)),
  }));
  return `${HEADER}${themeFonts(ux, themes)
    .map((font) => `@import "${FONT_PACKAGES[font]}";`)
    .join("\n")}

/* Theme: ${app.comment} */
${app.light}
${pages.map((p) => `\n/* The ${p.id} page's own theme: ${p.comment} */\n${p.light}\n`).join("")}
/* Touch screens get 44 px targets whatever the density. */
@media (pointer: coarse) {
  :root${pages.map((p) => `,\n  [data-page="${p.id}"]`).join("")} {
    --control-height: 2.75rem;
  }
}

/* A visitor who asks for less motion gets none, whatever the theme says. */
@media (prefers-reduced-motion: reduce) {
  :root${pages.map((p) => `,\n  [data-page="${p.id}"]`).join("")} {
    --motion-fast: 0ms;
    --motion-slow: 0ms;
    --motion-distance: 0px;
    --landing-motion: none;
    --hero-motion: none;
  }
}

${[app.dark, ...pages.map((p) => p.dark)].join("\n")}
${
  ux.aiBadge
    ? ""
    : `
/* The owner switched the badge on pictures an AI made off (aiBadge: false; src/kit/AiMark.tsx). */
[data-part="ai-mark"] {
  display: none;
}
`
}`;
}
